using System.Text;
using Ample.Core;

namespace Ample.Stack;

/// <summary>
/// Writes the Apache files AMPLE owns under etc\apache. httpd.conf is written once and then left to the user; the
/// generated files (ports, php, apps, ssl, projects) are rewritten whenever what they describe changes.
/// </summary>
public static class ApacheConfig
{
    private const string GeneratedHeader =
        "# Generated by AMPLE. Changes here are overwritten; put your own directives in etc/apache/custom/*.conf.";

    /// <summary>The certificate file Apache serves, relative to etc\apache.</summary>
    public const string ServerCertificate = "ssl/ample-local.crt";

    /// <summary>The private key file of <see cref="ServerCertificate"/>, relative to etc\apache.</summary>
    public const string ServerKey = "ssl/ample-local.key";

    /// <summary>Writes httpd.conf from the template unless the user already has one.</summary>
    /// <param name="paths">The stack.</param>
    /// <returns>True when the file was written; false when it existed.</returns>
    public static bool WriteHttpdConfIfMissing(AmplePaths paths)
    {
        if (File.Exists(paths.HttpdConf))
        {
            return false;
        }

        ConfigTemplates.WriteFile(paths.HttpdConf, ConfigTemplates.Read("apache/httpd.conf"));
        return true;
    }

    /// <summary>Writes ports.conf: the Listen lines.</summary>
    /// <param name="paths">The stack.</param>
    /// <param name="ports">The ports from the settings.</param>
    public static void WritePorts(AmplePaths paths, PortSettings ports)
    {
        var text = new StringBuilder();
        text.AppendLine(GeneratedHeader);
        text.AppendLine($"Listen {ports.Http}");
        text.AppendLine("<IfModule ssl_module>");
        text.AppendLine($"    Listen {ports.Https}");
        text.AppendLine("</IfModule>");
        ConfigTemplates.WriteFile(Path.Combine(paths.EtcApache, "ports.conf"), text.ToString());
    }

    /// <summary>Writes php.conf: mod_fcgid tuned for PHP, and the default PHP version for www and projects.</summary>
    /// <param name="paths">The stack.</param>
    /// <param name="defaultPhpVersion">The folder name under bin\php to run by default.</param>
    /// <param name="installedPhpVersions">Every version under bin\php; each gets its phpinfo page.</param>
    public static void WritePhp(AmplePaths paths, string defaultPhpVersion, IReadOnlyList<string> installedPhpVersions)
    {
        var text = new StringBuilder();
        text.AppendLine(GeneratedHeader);
        text.AppendLine();
        text.AppendLine("<IfModule fcgid_module>");
        text.AppendLine("    FcgidIOTimeout 120");
        text.AppendLine("    FcgidConnectTimeout 10");
        text.AppendLine("    FcgidBusyTimeout 300");
        text.AppendLine("    FcgidIdleTimeout 300");
        text.AppendLine("    FcgidProcessLifeTime 3600");
        text.AppendLine("    FcgidMaxProcesses 32");
        text.AppendLine("    FcgidMaxProcessesPerClass 16");
        text.AppendLine("    FcgidMaxRequestsPerProcess 1000");
        text.AppendLine("    # Uploads: mod_fcgid's default is 128 KB, which breaks every file upload.");
        text.AppendLine("    FcgidMaxRequestLen 268435456");
        text.AppendLine("    FcgidOutputBufferSize 65536");
        text.AppendLine();
        AppendInitialEnv(text, defaultPhpVersion, "    ");
        text.AppendLine();
        text.AppendLine("    # The default PHP for localhost and for projects that don't pick a version.");
        AppendPhpDirectory(text, "${AMPLE_ROOT}/www", defaultPhpVersion, "    ");
        AppendPhpDirectory(text, "${AMPLE_ROOT}/projects", defaultPhpVersion, "    ");
        text.AppendLine();
        text.AppendLine("    # http://localhost/_ample/php/<version>/ shows phpinfo() for that version.");
        foreach (string version in installedPhpVersions)
        {
            AppendPhpDirectory(text, $"${{AMPLE_ROOT}}/www/_ample/php/{version}", version, "    ");
        }
        text.AppendLine("</IfModule>");
        ConfigTemplates.WriteFile(Path.Combine(paths.EtcApache, "php.conf"), text.ToString());
    }

    /// <summary>Writes apps.conf: /ledger and /phpmyadmin, for this computer only.</summary>
    /// <param name="paths">The stack.</param>
    /// <param name="defaultPhpVersion">The PHP version the apps run on.</param>
    /// <param name="hasLedger">True adds the /ledger alias.</param>
    /// <param name="hasPhpMyAdmin">True adds the /phpmyadmin alias.</param>
    public static void WriteApps(AmplePaths paths, string defaultPhpVersion, bool hasLedger, bool hasPhpMyAdmin)
    {
        var text = new StringBuilder();
        text.AppendLine(GeneratedHeader);
        text.AppendLine("# The database tools answer to this computer only (Require local), never to the LAN.");
        if (hasLedger)
        {
            AppendApp(text, "ledger", defaultPhpVersion);
        }
        if (hasPhpMyAdmin)
        {
            AppendApp(text, "phpmyadmin", defaultPhpVersion);
        }
        ConfigTemplates.WriteFile(Path.Combine(paths.EtcApache, "apps.conf"), text.ToString());
    }

    /// <summary>Writes ssl.conf: TLS settings and HTTPS for localhost, active once the certificate exists.</summary>
    /// <param name="paths">The stack.</param>
    /// <param name="ports">The ports from the settings.</param>
    public static void WriteSsl(AmplePaths paths, PortSettings ports)
    {
        var text = new StringBuilder();
        text.AppendLine(GeneratedHeader);
        text.AppendLine("<IfModule ssl_module>");
        text.AppendLine("    SSLProtocol all -SSLv3 -TLSv1 -TLSv1.1");
        text.AppendLine("    SSLCipherSuite HIGH:!aNULL:!MD5");
        text.AppendLine("    SSLHonorCipherOrder off");
        text.AppendLine("    SSLSessionCache \"shmcb:${AMPLE_ROOT}/tmp/ssl_scache(512000)\"");
        text.AppendLine("    SSLSessionCacheTimeout 300");
        text.AppendLine();
        text.AppendLine($"    <IfFile \"${{AMPLE_ETC}}/{ServerKey}\">");
        text.AppendLine($"        <VirtualHost *:{ports.Https}>");
        text.AppendLine("            ServerName localhost");
        text.AppendLine("            DocumentRoot \"${AMPLE_ROOT}/www\"");
        text.AppendLine("            SSLEngine on");
        text.AppendLine($"            SSLCertificateFile \"${{AMPLE_ETC}}/{ServerCertificate}\"");
        text.AppendLine($"            SSLCertificateKeyFile \"${{AMPLE_ETC}}/{ServerKey}\"");
        text.AppendLine("        </VirtualHost>");
        text.AppendLine("    </IfFile>");
        text.AppendLine("</IfModule>");
        ConfigTemplates.WriteFile(Path.Combine(paths.EtcApache, "ssl.conf"), text.ToString());
    }

    /// <summary>
    /// Builds projects.conf: localhost first (so it stays the default host), then every project on HTTP and, for
    /// projects that want it, on HTTPS, each on its own PHP version.
    /// </summary>
    /// <param name="projects">The projects in the order they are written; folders must be full paths.</param>
    /// <param name="ports">The ports from the settings.</param>
    /// <param name="defaultPhpVersion">The PHP version for projects without one of their own.</param>
    /// <param name="installedPhpVersions">The versions under bin\php; a project naming another falls back.</param>
    /// <returns>The file's text.</returns>
    public static string BuildProjects(
        IReadOnlyList<Project> projects,
        PortSettings ports,
        string defaultPhpVersion,
        IReadOnlyCollection<string> installedPhpVersions)
    {
        var text = new StringBuilder();
        text.AppendLine(GeneratedHeader);
        text.AppendLine("# One virtual host per project from AMPLE's Projects page. localhost comes first on purpose:");
        text.AppendLine("# Apache answers unknown host names with the first virtual host.");
        text.AppendLine();

        AppendHost(
            text,
            ports.Http,
            "localhost",
            "${AMPLE_ROOT}/www",
            defaultPhpVersion,
            useSsl: false,
            withDirectory: false);
        foreach (Project project in projects)
        {
            string phpVersion = PhpVersionFor(project, defaultPhpVersion, installedPhpVersions);
            AppendHost(
                text,
                ports.Http,
                project.Host,
                AmplePaths.ConfigPath(project.Folder),
                phpVersion,
                useSsl: false,
                withDirectory: true,
                phpIni: CustomIni(project));
        }

        if (projects.Any(project => project.UseHttps))
        {
            text.AppendLine("<IfModule ssl_module>");
            text.AppendLine($"<IfFile \"${{AMPLE_ETC}}/{ServerKey}\">");
            text.AppendLine();
            foreach (Project project in projects.Where(project => project.UseHttps))
            {
                string phpVersion = PhpVersionFor(project, defaultPhpVersion, installedPhpVersions);
                AppendHost(
                    text,
                    ports.Https,
                    project.Host,
                    AmplePaths.ConfigPath(project.Folder),
                    phpVersion,
                    useSsl: true,
                    withDirectory: true,
                    phpIni: CustomIni(project));
            }
            text.AppendLine("</IfFile>");
            text.AppendLine("</IfModule>");
        }

        return text.ToString();
    }

    /// <summary>Writes projects.conf from <see cref="BuildProjects"/>.</summary>
    /// <param name="paths">The stack.</param>
    /// <param name="projects">The projects.</param>
    /// <param name="ports">The ports from the settings.</param>
    /// <param name="defaultPhpVersion">The PHP version for projects without one of their own.</param>
    public static void WriteProjects(
        AmplePaths paths,
        IReadOnlyList<Project> projects,
        PortSettings ports,
        string defaultPhpVersion)
    {
        string text = BuildProjects(projects, ports, defaultPhpVersion, paths.InstalledPhpVersions());
        ConfigTemplates.WriteFile(paths.ProjectsConf, text);
    }

    /// <summary>The PHP version a project runs on: its own when installed, else the default.</summary>
    /// <param name="project">The project.</param>
    /// <param name="defaultPhpVersion">The stack's default version.</param>
    /// <param name="installedPhpVersions">The versions under bin\php.</param>
    /// <returns>A folder name under bin\php.</returns>
    public static string PhpVersionFor(
        Project project,
        string defaultPhpVersion,
        IReadOnlyCollection<string> installedPhpVersions)
    {
        bool hasOwn = project.PhpVersion is { Length: > 0 } own
            && installedPhpVersions.Contains(own, StringComparer.OrdinalIgnoreCase);
        return hasOwn ? project.PhpVersion! : defaultPhpVersion;
    }

    /// <summary>A project's custom php.ini in config form, when it names one that exists.</summary>
    /// <param name="project">The project.</param>
    /// <returns>The file's path with forward slashes; null when the project uses the version's own php.ini.</returns>
    private static string? CustomIni(Project project) =>
        project.PhpIni is { Length: > 0 } ini && File.Exists(ini) ? AmplePaths.ConfigPath(ini) : null;

    /// <summary>Appends one VirtualHost section followed by a blank line.</summary>
    private static void AppendHost(
        StringBuilder text,
        int port,
        string hostName,
        string documentRoot,
        string phpVersion,
        bool useSsl,
        bool withDirectory,
        string? phpIni = null)
    {
        text.AppendLine($"<VirtualHost *:{port}>");
        text.AppendLine($"    ServerName {hostName}");
        text.AppendLine($"    DocumentRoot \"{documentRoot}\"");
        text.AppendLine($"    ErrorLog \"${{AMPLE_LOGS}}/{SafeFileName(hostName)}-error.log\"");
        AppendInitialEnv(text, phpVersion, "    ", phpIni);
        if (withDirectory)
        {
            AppendPhpDirectory(text, documentRoot, phpVersion, "    ");
        }
        if (useSsl)
        {
            text.AppendLine("    SSLEngine on");
            text.AppendLine($"    SSLCertificateFile \"${{AMPLE_ETC}}/{ServerCertificate}\"");
            text.AppendLine($"    SSLCertificateKeyFile \"${{AMPLE_ETC}}/{ServerKey}\"");
        }
        text.AppendLine("</VirtualHost>");
        text.AppendLine();
    }

    /// <summary>Appends the alias and directory for one app under apps\.</summary>
    private static void AppendApp(StringBuilder text, string folder, string phpVersion)
    {
        text.AppendLine();
        text.AppendLine($"Alias /{folder} \"${{AMPLE_ROOT}}/apps/{folder}\"");
        text.AppendLine($"<Directory \"${{AMPLE_ROOT}}/apps/{folder}\">");
        text.AppendLine("    Options FollowSymLinks ExecCGI");
        text.AppendLine("    AllowOverride All");
        text.AppendLine("    Require local");
        AppendHandler(text, phpVersion, "    ");
        text.AppendLine("</Directory>");
    }

    /// <summary>Appends a Directory section that grants access and runs .php files on one PHP version.</summary>
    private static void AppendPhpDirectory(StringBuilder text, string folder, string phpVersion, string indent)
    {
        text.AppendLine($"{indent}<Directory \"{folder}\">");
        text.AppendLine($"{indent}    Options Indexes FollowSymLinks ExecCGI");
        text.AppendLine($"{indent}    AllowOverride All");
        text.AppendLine($"{indent}    Require all granted");
        AppendHandler(text, phpVersion, indent + "    ");
        text.AppendLine($"{indent}</Directory>");
    }

    /// <summary>Appends the two lines that hand .php files to one version's php-cgi.exe.</summary>
    private static void AppendHandler(StringBuilder text, string phpVersion, string indent)
    {
        text.AppendLine($"{indent}AddHandler fcgid-script .php");
        text.AppendLine($"{indent}FcgidWrapper \"${{AMPLE_ROOT}}/bin/php/{phpVersion}/php-cgi.exe\" .php");
    }

    /// <summary>
    /// Appends the environment php-cgi needs on Windows. mod_fcgid starts it with an empty environment, so the
    /// system folders and a temp folder have to be handed over, along with the version's own folder for its DLLs.
    /// </summary>
    private static void AppendInitialEnv(StringBuilder text, string phpVersion, string indent, string? phpIni = null)
    {
        string phpFolder = "${AMPLE_ROOT}/bin/php/" + phpVersion;
        // PHPRC may name a file as well as a folder; a project's custom php.ini is handed over that way.
        string phprc = phpIni ?? phpFolder;
        string windows = Environment.GetFolderPath(Environment.SpecialFolder.Windows);
        windows = windows.Length == 0 ? "C:/Windows" : AmplePaths.ConfigPath(windows);
        string systemDrive = windows.Length >= 2 && windows[1] == ':' ? windows[..2] : "C:";
        text.AppendLine($"{indent}FcgidInitialEnv PHPRC \"{phprc}\"");
        text.AppendLine($"{indent}FcgidInitialEnv PATH \"{phpFolder};{windows}/System32;{windows}\"");
        text.AppendLine($"{indent}FcgidInitialEnv SystemRoot \"{windows}\"");
        text.AppendLine($"{indent}FcgidInitialEnv SystemDrive \"{systemDrive}\"");
        text.AppendLine($"{indent}FcgidInitialEnv TEMP \"${{AMPLE_ROOT}}/tmp\"");
        text.AppendLine($"{indent}FcgidInitialEnv TMP \"${{AMPLE_ROOT}}/tmp\"");
        text.AppendLine($"{indent}FcgidInitialEnv PHP_FCGI_MAX_REQUESTS 1000");
    }

    /// <summary>A host name as a log file name: letters, digits, dots and hyphens only.</summary>
    private static string SafeFileName(string hostName) =>
        new(hostName
            .Select(character => char.IsLetterOrDigit(character) || character is '.' or '-' ? character : '_')
            .ToArray());
}
